int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    // dp[a][b][c][turn] — turn: 0=Alice,1=Bob,2=Charlie
    static int dp[51][51][51][3];
    memset(dp, 0, sizeof(dp));

    // Base: if it's your turn and you have 0 cards, you lose for that turn's perspective,
    // but we only care about Alice winning from start.
    // We'll fill backwards: from states where someone just won.

    // Start from states where it's Alice's turn and she has 0 cards -> she already won.
    // But that's the end, so we propagate from those.
    // Actually easier: iterate over all states and compute from smaller totals upward.

    for (int a = 0; a <= N; a++) {
        for (int b = 0; b <= M; b++) {
            for (int c = 0; c <= K; c++) {
                for (int turn = 0; turn < 3; turn++) {
                    if (turn == 0 && a == 0) {
                        // Alice's turn but no cards -> Alice wins
                        // This state counts as 1 way (the way that got here)
                        dp[a][b][c][turn] = 1;
                        continue;
                    }
                    if (turn == 1 && b == 0) {
                        dp[a][b][c][turn] = 1;
                        continue;
                    }
                    if (turn == 2 && c == 0) {
                        dp[a][b][c][turn] = 1;
                        continue;
                    }

                    long long ways = 0;
                    if (turn == 0) {
                        // Alice plays a card
                        if (a > 0) {
                            // Plays 'a': next turn Alice
                            ways += dp[a-1][b][c][0];
                            // Plays 'b': next turn Bob
                            ways += dp[a-1][b][c][1];
                            // Plays 'c': next turn Charlie
                            ways += dp[a-1][b][c][2];
                        }
                    } else if (turn == 1) {
