                            ways += dp[a][b-1][c][0];
                            ways += dp[a][b-1][c][1];
                            ways += dp[a][b-1][c][2];
                        }
                    } else { // turn == 2
                        if (c > 0) {
                            ways += dp[a][b][c-1][0];
                            ways += dp[a][b][c-1][1];
                            ways += dp[a][b][c-1][2];
                        }
                    }
                    dp[a][b][c][turn] = ways % MOD;
                }
            }
        }
    }

    printf("%d\n", dp[N][M][K][0]);
    return 0;
}

