#define MOD 1000000007LL

/*
State:
dp[a][b][c][t] = number of ways for the game state where
- Alice has a cards remaining
- Bob has b cards remaining
- Charlie has c cards remaining
- current turn is t: 0=A, 1=B, 2=C
and starting from this state, Alice eventually wins.

Transition:
If it's player t's turn and their deck is empty, this state is unreachable in normal play,
so it contributes 0.

Otherwise, that player discards their top card.
If they had exactly 1 card, they win immediately by the rules.
So:
- if t == A and a == 1 => all possible top cards are winning for Alice
- if t == B and b == 1 => Alice loses immediately
- if t == C and c == 1 => Alice loses immediately

For larger deck sizes, the discarded top card can be:
'a' -> next turn Alice
'b' -> next turn Bob
'c' -> next turn Charlie
and the current player's remaining count decreases by 1.

Because each card position is independent and can be any of {a,b,c},
the number of initial deck configurations corresponding to a transition is multiplied by 1
for each choice of top card, and we sum over 3 possibilities.

We compute bottom-up by increasing total cards a+b+c.
*/

static long long dp[105][105][105][3];

int main(void) {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    for (int sum = 1; sum <= N + M + K; sum++) {
        for (int a = 0; a <= N; a++) {
            for (int b = 0; b <= M; b++) {
                int c = sum - a - b;
                if (c < 0 || c > K) continue;

                // Alice's turn
                if (a >= 1) {
                    if (a == 1) {
                        // Alice discards her last card, regardless of whether it's a/b/c, and wins.
                        dp[a][b][c][0] = 3;
                    } else {
                        long long val = 0;
                        val += dp[a - 1][b][c][0]; // top card 'a'
                        val += dp[a - 1][b][c][1]; // top card 'b'
                        val += dp[a - 1][b][c][2]; // top card 'c'
                        dp[a][b][c][0] = val % MOD;
                    }
                }

                // Bob's turn
                if (b >= 1) {
                    if (b == 1) {
                        // Bob discards his last card and wins, so Alice does not.
                        dp[a][b][c][1] = 0;
                    } else {
                        long long val = 0;
                        val += dp[a][b - 1][c][0]; // top card 'a'
                        val += dp[a][b - 1][c][1]; // top card 'b'
                        val += dp[a][b - 1][c][2]; // top card 'c'
                        dp[a][b][c][1] = val % MOD;
                    }
                }

                // Charlie's turn
                if (c >= 1) {
                    if (c == 1) {
                        // Charlie discards his last card and wins, so Alice does not.
                        dp[a][b][c][2] = 0;
                    } else {
                        long long val = 0;
                        val += dp[a][b][c - 1][0]; // top card 'a'
                        val += dp[a][b][c - 1][1]; // top card 'b'
                        val += dp[a][b][c - 1][2]; // top card 'c'
                        dp[a][b][c][2] = val % MOD;
                    }
                }
            }
        }
    }

    // The game starts with Alice's turn.
    printf("%lld\n", dp[N][M][K][0] % MOD);
    return 0;
}

