const int MOD = 1e9 + 7;

int64 dp[101][101][101][3];
bool vis[101][101][101][3];

int64 solve(int a, int b, int c, int turn) {
    if (a == 0 && b == 0 && c == 0) return 0;
    int64 &res = dp[a][b][c][turn];
    if (vis[a][b][c][turn]) return res;
    vis[a][b][c][turn] = true;
    res = 0;

    int total;
    if (turn == 0) total = a;
    else if (turn == 1) total = b;
    else total = c;

    if (total == 0) {
        // turn passes to someone else? Actually if a player has no cards but it's their turn, 
        // the game would have ended earlier. So this state shouldn't happen.
        return res = 0;
    }

    // Probability-like counting: each card is distinct.
    // Discard card of type 'a'
    if (a > 0 && (turn == 0)) {
        if (a == 1 && b == 0 && c == 0) {
            // Alice discards last card and wins
            res = (res + 1) % MOD;
        } else {
            res = (res + solve(a - 1, b, c, 0)) % MOD;
        }
    } else if (a > 0 && turn != 0) {
        if (a == 1 && b == 0 && c == 0) {
            // Alice wins because someone else discarded her last card? 
            // No, rule says player discards their own card. So this branch doesn't apply.
        } else {
            res = (res + solve(a - 1, b, c, 0)) % MOD;
        }
    }

    // Discard 'b'
    if (b > 0 && turn == 1) {
        if (b == 1 && a == 0 && c == 0) {
            res = (res + 0) % MOD; // Bob wins, not Alice
        } else {
            res = (res + solve(a, b - 1, c, 1)) % MOD;
        }
    } else if (b > 0 && turn != 1) {
        res = (res + solve(a, b - 1, c, 1)) % MOD;
    }

    // Discard 'c'
    if (c > 0 && turn == 2) {
        if (c == 1 && a == 0 && b == 0) {
            res = (res + 0) % MOD;
        } else {
            res = (res + solve(a, b, c - 1, 2)) % MOD;
        }
    } else if (c > 0 && turn != 2) {
        res = (res + solve(a, b, c - 1, 2)) % MOD;
    }

    // Multiply by number of ways to choose which card is on top:
    // Actually we need combinatorial counting: number of sequences leading to Alice winning.
    // We'll handle it by counting each card as distinct.
    return res;
}

