                            // Bob wins, not counted
                        } else {
                            ways = (ways + dp[a][b-1][c][1]) % MOD;
                        }
                    }
                    // Discard 'c'
                    if (c > 0) {
                        if (c == 1 && a == 0 && b == 0) {
                            // Charlie wins
                        } else {
                            ways = (ways + dp[a][b][c-1][2]) % MOD;
                        }
                    }
                    dp[a][b][c][t] = ways;
                    vis[a][b][c][t] = true;
                }
            }
        }
    }

    int64 ans = dp[N][M][K][0];
    cout << ans % MOD << "\n";

    return 0;
}

