static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    // dp[i][j][k][t]:
    // number of deck configurations for suffix lengths:
    // Alice has i remaining cards, Bob j, Charlie k,
    // and player t (0=A,1=B,2=C) is to move,
    // such that eventually Alice wins.
    //
    // We build from smaller lengths upward.
    //
    // Transition:
    // If current player has 0 cards, state is unreachable in actual play,
    // but we keep it as 0.
    //
    // If current player has exactly 1 card left, then discarding it ends game
    // immediately, so result depends only on whether current player is Alice.
    //
    // Otherwise, the top card can be a/b/c independently:
    // dp = sum of next states after removing one card and passing turn.
    //
    // Since only one player's count decreases in each transition,
    // we can fill in increasing order of i,j,k.

    int A = N, B = M, C = K;

    // store 3 states for each (i,j,k)
    vector<long long> dp((A + 1) * (B + 1) * (C + 1) * 3, 0);

    auto id = [&](int i, int j, int k, int t) {
        return ((((long long)i * (B + 1) + j) * (C + 1) + k) * 3 + t);
    };

    for (int i = 0; i <= A; ++i) {
        for (int j = 0; j <= B; ++j) {
            for (int k = 0; k <= C; ++k) {
                // Alice's turn
                if (i >= 1) {
                    if (i == 1) {
                        dp[id(i, j, k, 0)] = 1; // Alice discards last card and wins
                    } else {
                        long long val = 0;
                        val += dp[id(i - 1, j, k, 0)]; // top card 'a' -> Alice
                        val += dp[id(i - 1, j, k, 1)]; // top card 'b' -> Bob
                        val += dp[id(i - 1, j, k, 2)]; // top card 'c' -> Charlie
                        dp[id(i, j, k, 0)] = val % MOD;
                    }
                }

                // Bob's turn
                if (j >= 1) {
                    if (j == 1) {
                        dp[id(i, j, k, 1)] = 0; // Bob wins immediately, not Alice
                    } else {
                        long long val = 0;
                        val += dp[id(i, j - 1, k, 0)];
                        val += dp[id(i, j - 1, k, 1)];
                        val += dp[id(i, j - 1, k, 2)];
                        dp[id(i, j, k, 1)] = val % MOD;
                    }
                }

                // Charlie's turn
                if (k >= 1) {
                    if (k == 1) {
                        dp[id(i, j, k, 2)] = 0; // Charlie wins immediately, not Alice
                    } else {
                        long long val = 0;
                        val += dp[id(i, j, k - 1, 0)];
                        val += dp[id(i, j, k - 1, 1)];
                        val += dp[id(i, j, k - 1, 2)];
                        dp[id(i, j, k, 2)] = val % MOD;
                    }
                }
            }
        }
    }

    // Initially Alice starts.
    cout << dp[id(N, M, K, 0)] % MOD << '\n';
    return 0;
}

