public class CardGame {
    static final int MOD = 1_000_000_007;
    static Long[][][][] dp;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        int K = sc.nextInt();
        sc.close();

        long result = 0;
        // Iterate over all possible distributions of 'a','b','c' in Alice's, Bob's, Charlie's decks
        for (int aA = 0; aA <= N; aA++) {
            for (int bA = 0; bA <= N - aA; bA++) {
                int cA = N - aA - bA;
                for (int aB = 0; aB <= M; aB++) {
                    for (int bB = 0; bB <= M - aB; bB++) {
                        int cB = M - aB - bB;
                        for (int aC = 0; aC <= K; aC++) {
                            for (int bC = 0; bC <= K - aC; bC++) {
                                int cC = K - aC - bC;

                                // Initialize dp for this distribution
                                dp = new Long[N+1][M+1][K+1][3];
                                long ways = solve(aA, bA, cA, aB, bB, cB, aC, bC, cC, 0);
                                result = (result + ways) % MOD;
                            }
                        }
                    }
                }
            }
        }
        System.out.println(result);
    }

    static long solve(int aA, int bA, int cA, int aB, int bB, int cB, int aC, int bC, int cC, int turn) {
        int totalA = aA + bA + cA;
        int totalB = aB + bB + cB;
        int totalC = aC + bC + cC;

        if (turn == 0 && totalA == 0) return 0; // no cards to draw, shouldn't happen
        if (turn == 1 && totalB == 0) return 0;
        if (turn == 2 && totalC == 0) return 0;

        if (dp[aA][bA][cA][turn] != null) return dp[aA][bA][cA][turn];

        long res = 0;
        if (turn == 0) {
            // draw from Alice's deck
            if (aA > 0) {
                if (totalA == 1) { // last card
                    res = (res + 1) % MOD;
                } else {
                    res = (res + solve(aA-1, bA, cA, aB, bB, cB, aC, bC, cC, 0)) % MOD;
                }
            }
            if (bA > 0) {
                if (totalA == 1) {
                    // Alice draws 'b' as last card → Bob wins, Alice loses
                } else {
                    res = (res + solve(aA, bA-1, cA, aB, bB, cB, aC, bC, cC, 1)) % MOD;
                }
            }
            if (cA > 0) {
                if (totalA == 1) {
                    // Alice draws 'c' as last card → Charlie wins
                } else {
                    res = (res + solve(aA, bA, cA-1, aB, bB, cB, aC, bC, cC, 2)) % MOD;
                }
            }
        } else if (turn == 1) {
            if (aB > 0) {
                if (totalB == 1) {
                    // Bob draws 'a' as last → Alice wins
                    res = (res + 1) % MOD;
                } else {
                    res = (res + solve(aA, bA, cA, aB-1, bB, cB, aC, bC, cC, 0)) % MOD;
                }
            }
            if (bB > 0) {
                if (totalB == 1) {
                    // Bob wins
                } else {
                    res = (res + solve(aA, bA, cA, aB, bB-1, cB, aC, bC, cC, 1)) % MOD;
                }
            }
            if (cB > 0) {
                if (totalB == 1) {
                    // Charlie wins
                } else {
                    res = (res + solve(aA, bA, cA, aB, bB, cB-1, aC, bC, cC, 2)) % MOD;
                }
            }
        } else { // turn == 2 (Charlie)
            if (aC > 0) {
                if (totalC == 1) {
                    res = (res + 1) % MOD;
                } else {
                    res = (res + solve(aA, bA, cA, aB, bB, cB, aC-1, bC, cC, 0)) % MOD;
                }
            }
            if (bC > 0) {
                if (totalC == 1) {
                    // Bob wins
                } else {
                    res = (res + solve(aA, bA, cA, aB, bB, cB, aC, bC-1, cC, 1)) % MOD;
                }
            }
            if (cC > 0) {
                if (totalC == 1) {
                    // Charlie wins
                } else {
                    res = (res + solve(aA, bA, cA, aB, bB, cB, aC, bC, cC-1, 2)) % MOD;
                }
            }
        }

        dp[aA][bA][cA][turn] = res;
        return res;
    }
}

