public class Main {
    static final int MOD = 1_000_000_007;
    static long[][][][] dp;
    static long[] pow3;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt(), K = sc.nextInt();
        pow3 = new long[N + M + K + 1];
        pow3[0] = 1;
        for (int i = 1; i < pow3.length; i++) pow3[i] = pow3[i-1] * 3 % MOD;
        dp = new long[N+1][M+1][K+1][3];
        for (long[][][] a : dp) for (long[][] b : a) for (long[] c : b) Arrays.fill(c, -1);
        System.out.println(solve(N, M, K, 0));
    }

    static long solve(int i, int j, int k, int t) {
        if (dp[i][j][k][t] != -1) return dp[i][j][k][t];
        long res = 0;
        if (t == 0) {
            if (i == 1) res = 3 * pow3[j] % MOD * pow3[k] % MOD;
            else for (int c = 0; c < 3; c++) res = (res + solve(i-1, j, k, c)) % MOD;
        } else if (t == 1) {
            if (j == 1) res = 0;
            else for (int c = 0; c < 3; c++) res = (res + solve(i, j-1, k, c)) % MOD;
        } else {
            if (k == 1) res = 0;
            else for (int c = 0; c < 3; c++) res = (res + solve(i, j, k-1, c)) % MOD;
        }
        return dp[i][j][k][t] = res;
    }
}

