public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        int max = Math.max(N, Math.max(M, K));
        long[] pow3 = new long[max + 1];
        pow3[0] = 1;
        for (int i = 1; i <= max; i++) {
            pow3[i] = (pow3[i - 1] * 3) % MOD;
        }

        // dpA[i][j][k]: number of configurations of suffix decks
        // with remaining lengths i,j,k such that starting from Alice's turn, Alice wins.
        // Similarly dpB, dpC for Bob/Charlie to move.
        long[][][] dpA = new long[N + 1][M + 1][K + 1];
        long[][][] dpB = new long[N + 1][M + 1][K + 1];
        long[][][] dpC = new long[N + 1][M + 1][K + 1];

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= M; j++) {
                for (int k = 0; k <= K; k++) {
                    if (i == 0 && j == 0 && k == 0) continue;

                    // Alice's turn with i cards remaining in Alice, j in Bob, k in Charlie
                    if (i > 0) {
                        if (i == 1) {
                            // Alice discards last card and wins, regardless of the card
                            dpA[i][j][k] = (3L * pow3[j] % MOD) * pow3[k] % MOD;
                        } else {
                            long val = 0;
                            // top card = 'a' -> Alice moves again
                            val += dpA[i - 1][j][k];
                            // top card = 'b' -> Bob moves
                            val += dpB[i - 1][j][k];
                            // top card = 'c' -> Charlie moves
                            val += dpC[i - 1][j][k];
                            dpA[i][j][k] = val % MOD;
                        }
                    }

                    // Bob's turn
                    if (j > 0) {
                        if (j == 1) {
                            // Bob wins, so Alice does not
                            dpB[i][j][k] = 0;
                        } else {
                            long val = 0;
                            // top card = 'a' -> Alice moves
                            val += dpA[i][j - 1][k];
                            // top card = 'b' -> Bob moves again
                            val += dpB[i][j - 1][k];
                            // top card = 'c' -> Charlie moves
                            val += dpC[i][j - 1][k];
                            // Remaining arbitrary suffixes of Bob's deck are already counted in subproblems
                            dpB[i][j][k] = val % MOD;
                        }
                    }

                    // Charlie's turn
                    if (k > 0) {
                        if (k == 1) {
                            // Charlie wins, so Alice does not
                            dpC[i][j][k] = 0;
                        } else {
                            long val = 0;
                            // top card = 'a' -> Alice moves
                            val += dpA[i][j][k - 1];
                            // top card = 'b' -> Bob moves
                            val += dpB[i][j][k - 1];
                            // top card = 'c' -> Charlie moves again
                            val += dpC[i][j][k - 1];
                            dpC[i][j][k] = val % MOD;
                        }
                    }
                }
            }
        }

        System.out.println(dpA[N][M][K] % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

MOD = 10**9+7

def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    N, M, K = map(int, input_data)
    max_n = N + M + K
    fact = [1] * (max_n + 1)
    invfact = [1] * (max_n + 1)
    for i in range(1, max_n+1):
        fact[i] = fact[i-1] * i % MOD
    invfact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

    ans = 0
    pow3 = [1] * (max_n + 1)
    for i in range(1, max_n+1):
        pow3[i] = pow3[i-1] * 3 % MOD

    for y in range(0, M+1):
        for z in range(0, K+1):
            # y = Bob turns, z = Charlie turns
            # b_a+b_b+b_c = y
            # c_a+c_b+c_c = z
            # constraints: b_a+c_a <= N-1, b_b+c_b <= y, b_c+c_c <= z
            # iterate over b_a, b_b, c_a, c_b, c_c
            for b_a in range(0, y+1):
                for b_b in range(0, y - b_a + 1):
                    b_c = y - b_a - b_b
                    for c_a in range(0, z+1):
                        if b_a + c_a > N-1:
                            continue
                        for c_b in range(0, z - c_a + 1):
                            c_c = z - c_a - c_b
                            if b_b + c_b > y or b_c + c_c > z:
                                continue
                            a_a = N-1 - (b_a + c_a)
                            a_b = y - (b_b + c_b)
                            a_c = z - (b_c + c_c)
                            if a_a < 0 or a_b < 0 or a_c < 0:
                                continue
                            ways = fact[N-1] * invfact[a_a] % MOD * invfact[a_b] % MOD * invfact[a_c] % MOD
                            ways = ways * fact[y] % MOD * invfact[b_a] % MOD * invfact[b_b] % MOD * invfact[b_c] % MOD
                            ways = ways * fact[z] % MOD * invfact[c_a] % MOD * invfact[c_b] % MOD * invfact[c_c] % MOD
                            ways = ways * pow3[1 + (M-y) + (K-z)] % MOD
                            ans = (ans + ways) % MOD
    print(ans)

if __name__ == "__main__":
    solve()
